#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAX_N 1000
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point a, b, c;
} Triangle;

// distance between two points
double dist(Point p1, Point p2) {
    double dx = p1.x - p2.x;
    double dy = p1.y - p2.y;
    return sqrt(dx*dx + dy*dy);
}

// check if point p is on line segment from a to b (within tolerance)
int on_segment(Point a, Point b, Point p) {
    double d_ab = dist(a, b);
    double d_ap = dist(a, p);
    double d_pb = dist(p, b);
    return fabs(d_ab - (d_ap + d_pb)) < 0.01 + EPS;
}

// check if distance from point p to line segment ab <= d (with tolerance 0.01)
int point_to_segment_le(Point a, Point b, Point p, double d) {
    double len2 = (b.x - a.x)*(b.x - a.x) + (b.y - a.y)*(b.y - a.y);
    if (len2 < EPS) { // a and b are same point
        return dist(a, p) <= d + 0.01;
    }
    double t = ((p.x - a.x)*(b.x - a.x) + (p.y - a.y)*(b.y - a.y)) / len2;
    Point closest;
    if (t < 0) {
        closest = a;
    } else if (t > 1) {
        closest = b;
    } else {
        closest.x = a.x + t * (b.x - a.x);
        closest.y = a.y + t * (b.y - a.y);
    }
    return dist(closest, p) <= d + 0.01;
}

// check if any point of triangle t2 is within distance d of any point of triangle t1
int can_illuminate(Triangle t1, Triangle t2, double d) {
    Point pts1[] = {t1.a, t1.b, t1.c};
    Point pts2[] = {t2.a, t2.b, t2.c};
    // check vertex to vertex
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (dist(pts1[i], pts2[j]) <= d + 0.01) return 1;
        }
    }
    // check vertex to edge
    Point edges1[3][2] = {{t1.a, t1.b}, {t1.b, t1.c}, {t1.c, t1.a}};
    Point edges2[3][2] = {{t2.a, t2.b}, {t2.b, t2.c}, {t2.c, t2.a}};
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (point_to_segment_le(edges1[i][0], edges1[i][1], pts2[j], d)) return 1;
            if (point_to_segment_le(edges2[j][0], edges2[j][1], pts1[i], d)) return 1;
        }
    }
    // edge to edge: check if any endpoint of one edge is within distance d of the other edge
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (point_to_segment_le(edges1[i][0], edges1[i][1], edges2[j][0], d)) return 1;
            if (point_to_segment_le(edges1[i][0], edges1[i][1], edges2[j][1], d)) return 1;
        }
    }
    return 0;
}

// adjacency matrix and graph for BFS/DFS
int adj[MAX_N][MAX_N];
int adj_size[MAX_N];
int visited[MAX_N];

void dfs(int u, int n) {
    visited[u] = 1;
    for (int i = 0; i < adj_size[u]; i++) {
        int v = adj[u][i];
        if (!visited[v]) dfs(v, n);
    }
}

int main() {
    int n;
    double d;
    scanf("%d %lf", &n, &d);

    Triangle tri[MAX_N];
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf %lf %lf %lf", 
              &tri[i].a.x, &tri[i].a.y,
              &tri[i].b.x, &tri[i].b.y,
              &tri[i].c.x, &tri[i].c.y);
    }

    // build graph: edge if one can illuminate the other
    for (int i = 0; i < n; i++) {
        adj_size[i] = 0;
        for (int j = 0; j < n; j++) {
            if (i != j && can_illuminate(tri[i], tri[j], d)) {
                adj[i][adj_size[i]++] = j;
            }
        }
    }

    // count connected components
    int components = 0;
    for (int i = 0; i < n; i++) visited[i] = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            components++;
            dfs(i, n);
        }
    }

    printf("%d\n", components);
    return 0;
}

