double dot(P a, P b) { return a.x*b.x+a.y*b.y; }
double cross(P a, P b) { return a.x*b.y-a.y*b.x; }
P sub(P a, P b) { P r; r.x=a.x-b.x; r.y=a.y-b.y; return r; }

double dist_ps(P p, P a, P b) {
    P ab=sub(b,a), ap=sub(p,a);
    double t=dot(ap,ab)/dot(ab,ab);
    if(t<0)t=0; if(t>1)t=1;
    P c; c.x=a.x+t*ab.x; c.y=a.y+t*ab.y;
    return dist_pp(p,c);
}

double dist_ss(P a,P b,P c,P d) {
    double r=dist_ps(a,c,d); if(dist_ps(b,c,d)<r)r=dist_ps(b,c,d);
    if(dist_ps(c,a,b)<r)r=dist_ps(c,a,b); if(dist_ps(d,a,b)<r)r=dist_ps(d,a,b);
    return r;
}

double tri_dist(T *a, T *b) {
