#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define EPS 0.01

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point p[3];
    Point apex;
    Point b1, b2;
} Triangle;

static double dist2(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy;
}

static int same_point(Point a, Point b) {
    return sqrt(dist2(a, b)) <= EPS;
}

static Point sub(Point a, Point b) {
    Point r = {a.x - b.x, a.y - b.y};
    return r;
}

static double dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

static double cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

static double norm2(Point a) {
    return a.x * a.x + a.y * a.y;
}

static int point_on_segment(Point p, Point a, Point b) {
    Point ab = sub(b, a), ap = sub(p, a), bp = sub(p, b);
    double len2 = norm2(ab);
    if (len2 == 0.0) return sqrt(dist2(p, a)) <= EPS;

    double t = dot(ap, ab) / len2;
    if (t < 0.0) t = 0.0;
    if (t > 1.0) t = 1.0;
    Point proj = {a.x + t * ab.x, a.y + t * ab.y};
    return sqrt(dist2(p, proj)) <= EPS;
}

static int segment_intersect(Point a, Point b, Point c, Point d) {
    if (point_on_segment(a, c, d) || point_on_segment(b, c, d) ||
        point_on_segment(c, a, b) || point_on_segment(d, a, b))
        return 1;

    Point ab = sub(b, a), ac = sub(c, a), ad = sub(d, a);
    Point cd = sub(d, c), ca = sub(a, c), cb = sub(b, c);

    double c1 = cross(ab, ac), c2 = cross(ab, ad);
    double c3 = cross(cd, ca), c4 = cross(cd, cb);

    if ((c1 > EPS && c2 < -EPS || c1 < -EPS && c2 > EPS) &&
        (c3 > EPS && c4 < -EPS || c3 < -EPS && c4 > EPS))
        return 1;
    return 0;
}

static int point_in_triangle_or_on(Point p, Triangle *t) {
    if (point_on_segment(p, t->p[0], t->p[1]) ||
        point_on_segment(p, t->p[1], t->p[2]) ||
        point_on_segment(p, t->p[2], t->p[0]))
        return 1;

    Point a = t->p[0], b = t->p[1], c = t->p[2];
    double c1 = cross(sub(b, a), sub(p, a));
    double c2 = cross(sub(c, b), sub(p, b));
    double c3 = cross(sub(a, c), sub(p, c));

    int pos = (c1 >= -EPS) + (c2 >= -EPS) + (c3 >= -EPS);
    int neg = (c1 <= EPS) + (c2 <= EPS) + (c3 <= EPS);
    return (pos == 3 || neg == 3);
}

static int segment_hits_triangle(Point a, Point b, Triangle *t) {
    if (point_in_triangle_or_on(a, t) || point_in_triangle_or_on(b, t))
        return 1;
    if (segment_intersect(a, b, t->p[0], t->p[1])) return 1;
    if (segment_intersect(a, b, t->p[1], t->p[2])) return 1;
    if (segment_intersect(a, b, t->p[2], t->p[0])) return 1;
    return 0;
}

static void identify_triangle(Triangle *t) {
    double d01 = dist2(t->p[0], t->p[1]);
    double d12 = dist2(t->p[1], t->p[2]);
    double d20 = dist2(t->p[2], t->p[0]);

    if (fabs(d01 - d12) <= 1e-7) {
        t->apex = t->p[1];
        t->b1 = t->p[0];
        t->b2 = t->p[2];
    } else if (fabs(d12 - d20) <= 1e-7) {
        t->apex = t->p[2];
        t->b1 = t->p[1];
        t->b2 = t->p[0];
    } else {
        t->apex = t->p[0];
        t->b1 = t->p[1];
        t->b2 = t->p[2];
    }
}

int main(void) {
    int n;
    double L;
    if (scanf("%d %lf", &n, &L) != 2) return 0;

    Triangle *tri = (Triangle *)malloc(sizeof(Triangle) * n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 3; j++) {
            scanf("%lf %lf", &tri[i].p[j].x, &tri[i].p[j].y);
        }
        identify_triangle(&tri[i]);
    }

    unsigned long long *reach = (unsigned long long *)calloc(n, sizeof(unsigned long long));

    for (int i = 0; i < n; i++) {
        reach[i] |= (1ULL << i);

        Point mid = {(tri[i].b1.x + tri[i].b2.x) / 2.0, (tri[i].b1.y + tri[i].b2.y) / 2.0};
        Point dir = sub(mid, tri[i].apex);
        double len = sqrt(norm2(dir));
        if (len == 0.0) continue;

        Point end = {
            tri[i].apex.x + dir.x / len * L,
            tri[i].apex.y + dir.y / len * L
        };

        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            if (segment_hits_triangle(tri[i].apex, end, &tri[j])) {
                reach[i] |= (1ULL << j);
            }
        }
    }

    // Transitive closure on bitmasks
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if ((reach[i] >> k) & 1ULL) {
                reach[i] |= reach[k];
            }
        }
    }

    // SCC by mutual reachability
    int *comp = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) comp[i] = -1;

    int compCnt = 0;
    for (int i = 0; i < n; i++) {
        if (comp[i] != -1) continue;
        comp[i] = compCnt;
        for (int j = i + 1; j < n; j++) {
            if (comp[j] == -1 &&
                ((reach[i] >> j) & 1ULL) &&
                ((reach[j] >> i) & 1ULL)) {
                comp[j] = compCnt;
            }
        }
        compCnt++;
    }

    int *indeg = (int *)calloc(compCnt, sizeof(int));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && ((reach[i] >> j) & 1ULL) && comp[i] != comp[j]) {
                indeg[comp[j]] = 1;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < compCnt; i++) {
        if (indeg[i] == 0) ans++;
    }

    printf("%d\n", ans);

    free(tri);
    free(reach);
    free(comp);
    free(indeg);
    return 0;
}

