struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}
};

double dist(const Point& a, const Point& b) {
    return sqrt((a.x - b.x)*(a.x - b.x) + (a.y - b.y)*(a.y - b.y));
}

struct Triangle {
    Point a, b, c;
};

double minX, maxX, minY, maxY;

void boundingBox(const Triangle& t) {
    minX = min({t.a.x, t.b.x, t.c.x});
    maxX = max({t.a.x, t.b.x, t.c.x});
    minY = min({t.a.y, t.b.y, t.c.y});
    maxY = max({t.a.y, t.b.y, t.c.y});
}

bool rectsOverlap(double l1x, double r1x, double l1y, double r1y,
                  double l2x, double r2x, double l2y, double r2y) {
    if (r1x + 0.01 < l2x || r2x + 0.01 < l1x) return false;
    if (r1y + 0.01 < l2y || r2y + 0.01 < l1y) return false;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    double D;
    cin >> N >> D;
    vector<Triangle> tri(N);
    for (int i = 0; i < N; i++) {
        cin >> tri[i].a.x >> tri[i].a.y
            >> tri[i].b.x >> tri[i].b.y
            >> tri[i].c.x >> tri[i].c.y;
    }

    vector<vector<int>> adj(N);
    for (int i = 0; i < N; i++) {
        boundingBox(tri[i]);
        double r1x = maxX + D, l1x = minX - D;
        double r1y = maxY + D, l1y = minY - D;
        for (int j = i+1; j < N; j++) {
            boundingBox(tri[j]);
            double r2x = maxX + D, l2x = minX - D;
            double r2y = maxY + D, l2y = minY - D;
            if (rectsOverlap(l1x, r1x, l1y, r1y, l2x, r2x, l2y, r2y)) {
                adj[i].push_back(j);
                adj[j].push_back(i);
            }
        }
    }

    int ans = N;
    for (int mask = 0; mask < (1 << N); mask++) {
        vector<bool> illuminated(N, false);
        for (int i = 0; i < N; i++) {
            if (mask & (1 << i)) {
                illuminated[i] = true;
                for (int v : adj[i]) {
                    illuminated[v] = true;
                }
            }
        }
        bool all = true;
        for (bool b : illuminated) if (!b) { all = false; break; }
        if (all) ans = min(ans, __builtin_popcount(mask));
    }

    cout << ans << "\n";
    return 0;
}

