typedef double ld;
typedef pair<ld,ld> P;

ld dist_point_segment(P p, P a, P b) {
    ld dx = b.first-a.first, dy = b.second-a.second;
    if (dx==0 && dy==0) return hypot(p.first-a.first, p.second-a.second);
    ld t = ((p.first-a.first)*dx + (p.second-a.second)*dy)/(dx*dx+dy*dy);
    t = max((ld)0, min((ld)1, t));
    return hypot(p.first-(a.first+t*dx), p.second-(a.second+t*dy));
}

ld dist_seg_seg(P a, P b, P c, P d) {
    ld r = min({dist_point_segment(a,c,d), dist_point_segment(b,c,d),
                dist_point_segment(c,a,b), dist_point_segment(d,a,b)});
    return r;
}

ld dist_triangles(vector<P>& t1, vector<P>& t2) {
    // Check if they intersect first - but let's just compute min edge-edge distance
    // Also need to check if one is inside the other
    ld mn = 1e18;
    for (int i=0;i<3;i++)
        for (int j=0;j<3;j++)
            mn = min(mn, dist_seg_seg(t1[i],t1[(i+1)%3],t2[j],t2[(j+1)%3]));
    return mn;
}

