#include <bits/stdc++.h>
using namespace std;

static const double EPS = 1e-2 + 1e-9;

struct Point {
    double x, y;
};

struct Triangle {
    Point p[3];
};

double dist2(const Point& a, const Point& b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy;
}

double dist(const Point& a, const Point& b) {
    return sqrt(dist2(a, b));
}

Point operator+(const Point& a, const Point& b) { return {a.x + b.x, a.y + b.y}; }
Point operator-(const Point& a, const Point& b) { return {a.x - b.x, a.y - b.y}; }
Point operator*(const Point& a, double t) { return {a.x * t, a.y * t}; }

double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
double cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }
double norm(const Point& a) { return sqrt(dot(a, a)); }

bool samePoint(const Point& a, const Point& b) {
    return dist(a, b) <= EPS;
}

double pointSegmentDistance(const Point& p, const Point& a, const Point& b) {
    Point ab = b - a;
    double len2 = dot(ab, ab);
    if (len2 == 0.0) return dist(p, a);
    double t = dot(p - a, ab) / len2;
    t = max(0.0, min(1.0, t));
    Point proj = a + ab * t;
    return dist(p, proj);
}

bool pointOnSegment(const Point& p, const Point& a, const Point& b) {
    return pointSegmentDistance(p, a, b) <= EPS;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double L;
    cin >> n >> L;

    vector<Triangle> tri(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 3; ++j) {
            cin >> tri[i].p[j].x >> tri[i].p[j].y;
        }
    }

    // Build directed graph:
    // i -> j if touching triangle i lights triangle j.
    //
    // Since all triangles are isosceles and equal-sized, for each triangle:
    // - find the apex: the vertex shared by the two equal sides
    // - the light rectangle starts from the base and extends outward from the apex
    //
    // Geometrically, triangle j is lit by i iff at least one vertex of j lies
    // inside/on the rectangle (with 0.01 tolerance). Because triangles do not
    // overlap/touch, this is sufficient for this problem setting.
    vector<vector<int>> g(n);

    for (int i = 0; i < n; ++i) {
        // Identify apex of isosceles triangle i.
        int apex = -1, b1 = -1, b2 = -1;
        double d01 = dist(tri[i].p[0], tri[i].p[1]);
        double d12 = dist(tri[i].p[1], tri[i].p[2]);
        double d20 = dist(tri[i].p[2], tri[i].p[0]);

        if (fabs(d01 - d20) <= EPS) {
            apex = 0; b1 = 1; b2 = 2;
        } else if (fabs(d01 - d12) <= EPS) {
            apex = 1; b1 = 0; b2 = 2;
        } else {
            apex = 2; b1 = 0; b2 = 1;
        }

        Point A = tri[i].p[apex];
        Point B = tri[i].p[b1];
        Point C = tri[i].p[b2];

        Point M = {(B.x + C.x) / 2.0, (B.y + C.y) / 2.0};
        Point dir = M - A;
        double len = norm(dir);
        if (len == 0.0) continue;
        dir = dir * (1.0 / len);

        // Rectangle corners: base BC, extended by length L away from apex
        Point shift = dir * L;
        Point R1 = B;
        Point R2 = C;
        Point R3 = C + shift;
        Point R4 = B + shift;

        // For robust point-in-rectangle test, use projection on edge directions.
        Point e1 = R2 - R1; // along base
        Point e2 = R4 - R1; // extension direction
        double e1len2 = dot(e1, e1);
        double e2len2 = dot(e2, e2);

        for (int j = 0; j < n; ++j) if (i != j) {
            bool lit = false;
            for (int k = 0; k < 3 && !lit; ++k) {
                Point P = tri[j].p[k];
                Point v = P - R1;

                double t1 = (e1len2 == 0.0 ? 0.0 : dot(v, e1) / e1len2);
                double t2 = (e2len2 == 0.0 ? 0.0 : dot(v, e2) / e2len2);

                // Distance to rectangle boundary for tolerance handling
                Point proj;
                double ct1 = min(1.0, max(0.0, t1));
                double ct2 = min(1.0, max(0.0, t2));
                proj = R1 + e1 * ct1 + e2 * ct2;

                if ((t1 >= -EPS && t1 <= 1.0 + EPS &&
                     t2 >= -EPS && t2 <= 1.0 + EPS) ||
                    dist(P, proj) <= EPS) {
                    lit = true;
                }
            }
            if (lit) g[i].push_back(j);
        }
    }

    // SCC decomposition (Kosaraju)
    vector<int> vis(n, 0), order;
    function<void(int)> dfs1 = [&](int u) {
        vis[u] = 1;
        for (int v : g[u]) if (!vis[v]) dfs1(v);
        order.push_back(u);
    };
    for (int i = 0; i < n; ++i) if (!vis[i]) dfs1(i);

    vector<vector<int>> rg(n);
    for (int u = 0; u < n; ++u)
        for (int v : g[u])
            rg[v].push_back(u);

    vector<int> comp(n, -1);
    int cc = 0;
    function<void(int)> dfs2 = [&](int u) {
        comp[u] = cc;
        for (int v : rg[u]) if (comp[v] == -1) dfs2(v);
    };

    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];
        if (comp[u] == -1) {
            dfs2(u);
            ++cc;
        }
    }

    vector<int> indeg(cc, 0);
    for (int u = 0; u < n; ++u) {
        for (int v : g[u]) {
            if (comp[u] != comp[v]) indeg[comp[v]]++;
        }
    }

    int ans = 0;
    for (int i = 0; i < cc; ++i) if (indeg[i] == 0) ans++;

    cout << ans << '\n';
    return 0;
}

