    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
        double dist(Point p) {
            double dx = this.x - p.x;
            double dy = this.y - p.y;
            return Math.sqrt(dx*dx + dy*dy);
        }
    }

    static class Triangle {
        Point[] vertices = new Point[3];
        Triangle(Point a, Point b, Point c) {
            vertices[0] = a;
            vertices[1] = b;
            vertices[2] = c;
        }
    }

    static final double EPS = 1e-9;

    // Check if point p is within distance d of any vertex of triangle t
    static boolean withinDistance(Point p, Triangle t, double d) {
        for (Point v : t.vertices) {
            if (p.dist(v) <= d + EPS) return true;
        }
        return false;
    }

    // Check if triangle t1 can illuminate triangle t2 with light distance d
    static boolean canIlluminate(Triangle t1, Triangle t2, double d) {
        // Check if any vertex of t1 is within d of any vertex of t2
        for (Point v1 : t1.vertices) {
            for (Point v2 : t2.vertices) {
                if (v1.dist(v2) <= d + EPS) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null && !line.trim().isEmpty()) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length == 0) continue;
            int N = Integer.parseInt(parts[0]);
            double D = Double.parseDouble(parts[1]);

            Triangle[] triangles = new Triangle[N];
            for (int i = 0; i < N; i++) {
                // Read 6 numbers for 3 vertices
                while (true) {
                    line = br.readLine();
                    if (line == null) break;
                    line = line.trim();
                    if (!line.isEmpty()) break;
                }
                if (line == null) break;
                parts = line.split("\\s+");
                double x1 = Double.parseDouble(parts[0]);
                double y1 = Double.parseDouble(parts[1]);
                double x2 = Double.parseDouble(parts[2]);
                double y2 = Double.parseDouble(parts[3]);
                double x3 = Double.parseDouble(parts[4]);
                double y3 = Double.parseDouble(parts[5]);
                triangles[i] = new Triangle(new Point(x1,y1), new Point(x2,y2), new Point(x3,y3));
            }

            // Build graph
            List<Integer>[] adj = new ArrayList[N];
            for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                for (int j = i+1; j < N; j++) {
                    if (canIlluminate(triangles[i], triangles[j], D)) {
                        adj[i].add(j);
                        adj[j].add(i);
                    }
                }
            }

            // Minimum touches = minimum number of vertices to cover all edges
            // This is Minimum Vertex Cover in a general graph - NP-hard
            // But N is small? Not specified. We'll use brute force for N <= 20,
            // otherwise heuristic / greedy. Since problem likely expects small N,
            // we implement exact algorithm using bitmask DP.

            int result = Integer.MAX_VALUE;
            // If N is small enough for brute force (<= 20)
            if (N <= 20) {
                // Check all subsets
                for (int mask = 0; mask < (1<<N); mask++) {
                    int bits = Integer.bitCount(mask);
                    if (bits >= result) continue;
                    boolean covered = true;
                    // Check all edges
                    for (int u = 0; u < N && covered; u++) {
                        if ((mask & (1<<u)) != 0) continue; // u is selected
                        for (int v : adj[u]) {
                            if ((mask & (1<<v)) == 0) { // v not selected
                                covered = false;
                                break;
                            }
                        }
                    }
                    if (covered) {
                        result = bits;
                    }
                }
            } else {
                // Greedy approximation: repeatedly pick vertex with highest degree
                boolean[] covered = new boolean[N];
                int touches = 0;
                while (true) {
                    // Find uncovered edge
                    int best = -1;
                    int bestDeg = -1;
                    for (int u = 0; u < N; u++) {
                        if (covered[u]) continue;
                        int deg = 0;
                        for (int v : adj[u]) {
                            if (!covered[v]) deg++;
                        }
                        if (deg > bestDeg) {
                            bestDeg = deg;
                            best = u;
                        }
                    }
                    if (best == -1) break;
                    // Touch this triangle
                    touches++;
                    covered[best] = true;
                    // Also cover all its neighbors (since they become illuminated)
                    // Actually, if we touch a triangle, it illuminates all adjacent triangles
                    // So we mark them as covered
                    for (int v : adj[best]) {
                        covered[v] = true;
                    }
                }
                result = touches;
            }

            System.out.println(result);
        }
    }
}

