import java.util.*;

/*
We model each triangle as a node.
Touching a triangle lights every triangle that intersects the rectangle of light
emitted from one of its equal sides outward by distance d.

Then:
- Build a directed graph: i -> j if touching triangle i can light triangle j.
- Condense SCCs. Inside an SCC, touching one lights all in that SCC.
- Minimum touches needed to light all triangles = number of source SCCs in the DAG.

Geometry notes:
- Each triangle is isosceles. We identify the apex as the vertex adjacent to the two equal sides.
- For each of the two equal sides, the light rectangle is the strip outside the triangle:
  side segment AB and outward normal of length d.
- Another triangle is lit if it intersects this closed rectangle (with epsilon 0.01).

Intersection with rectangle is checked by:
- any triangle vertex inside/on rectangle
- any rectangle corner inside/on triangle
- any triangle edge intersects any rectangle edge
This is sufficient for convex polygons.

Input format assumed:
n d
then for each triangle, 3 points: x y x y x y

Output:
minimum number of touches
*/

public class Main {
    static final double EPS = 0.01;
    static final double LEN_EPS = 1e-7;

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }

        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        Point mul(double k) { return new Point(x * k, y * k); }
    }

    static double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
    static double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
    static double norm2(Point a) { return dot(a, a); }
    static double dist(Point a, Point b) { return Math.hypot(a.x - b.x, a.y - b.y); }

    static class Triangle {
        Point[] p = new Point[3];
        int apex; // index of apex vertex
        Triangle(Point a, Point b, Point c) {
            p[0] = a; p[1] = b; p[2] = c;
            apex = findApex();
        }

        int findApex() {
            double d01 = dist(p[0], p[1]);
            double d12 = dist(p[1], p[2]);
            double d20 = dist(p[2], p[0]);

            if (Math.abs(d01 - d20) <= EPS) return 0; // sides from p0 equal
            if (Math.abs(d01 - d12) <= EPS) return 1; // sides from p1 equal
            return 2; // sides from p2 equal
        }

        // returns the two equal sides as pairs (apex, other)
        int[][] equalSides() {
            int a = apex;
            int b = (a + 1) % 3;
            int c = (a + 2) % 3;
            return new int[][]{{a, b}, {a, c}};
        }
    }

    static class Rect {
        Point[] q = new Point[4]; // in order
        Rect(Point a, Point b, Point c, Point d) {
            q[0] = a; q[1] = b; q[2] = c; q[3] = d;
        }
    }

    static Rect buildLightRect(Triangle t, int i, int j, double d) {
        Point A = t.p[i], B = t.p[j];
        Point side = B.sub(A);

        // Determine outward normal using the third vertex.
        int k = 3 - i - j;
        Point C = t.p[k];

        Point n1 = new Point(-side.y, side.x); // left normal
        double len = Math.hypot(n1.x, n1.y);
        if (len < LEN_EPS) return null;
        n1 = n1.mul(1.0 / len);

        // choose normal pointing away from triangle interior
        // if C is on positive side of AB wrt n1, interior lies in direction n1, so outward is -n1
        double s = dot(C.sub(A), n1);
        Point out = (s > 0 ? n1.mul(-1) : n1).mul(d);

        Point A2 = A.add(out);
        Point B2 = B.add(out);
        return new Rect(A, B, B2, A2);
    }

    static boolean pointOnSegment(Point p, Point a, Point b) {
        if (distancePointSegment(p, a, b) > EPS) return false;
        return dot(p.sub(a), p.sub(b)) <= EPS;
    }

    static double distancePointSegment(Point p, Point a, Point b) {
        Point ab = b.sub(a);
        double ab2 = norm2(ab);
        if (ab2 < LEN_EPS) return dist(p, a);
        double t = dot(p.sub(a), ab) / ab2;
        t = Math.max(0, Math.min(1, t));
        Point proj = a.add(ab.mul(t));
        return dist(p, proj);
    }

    static boolean pointInConvexPolygon(Point p, Point[] poly) {
        int n = poly.length;
        double sign = 0;
        for (int i = 0; i < n; i++) {
            Point a = poly[i], b = poly[(i + 1) % n];
            double cr = cross(b.sub(a), p.sub(a));
            if (Math.abs(cr) <= EPS) {
                if (pointOnSegment(p, a, b)) return true;
                continue;
            }
            if (sign == 0) sign = cr;
            else if (sign * cr < -EPS) return false;
        }
        return true;
    }

    static int sgn(double x) {
        if (x > EPS) return 1;
        if (x < -EPS) return -1;
        return 0;
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        if (distancePointSegment(a, c, d) <= EPS) return true;
        if (distancePointSegment(b, c, d) <= EPS) return true;
        if (distancePointSegment(c, a, b) <= EPS) return true;
        if (distancePointSegment(d, a, b) <= EPS) return true;

        double c1 = cross(b.sub(a), c.sub(a));
        double c2 = cross(b.sub(a), d.sub(a));
        double c3 = cross(d.sub(c), a.sub(c));
        double c4 = cross(d.sub(c), b.sub(c));
        return sgn(c1) * sgn(c2) < 0 && sgn(c3) * sgn(c4) < 0;
    }

    static boolean triangleIntersectsRect(Triangle t, Rect r) {
        Point[] tri = t.p;
        Point[] rec = r.q;

        for (Point p : tri) if (pointInConvexPolygon(p, rec)) return true;
        for (Point p : rec) if (pointInConvexPolygon(p, tri)) return true;

        for (int i = 0; i < 3; i++) {
            Point a = tri[i], b = tri[(i + 1) % 3];
            for (int j = 0; j < 4; j++) {
                Point c = rec[j], d = rec[(j + 1) % 4];
                if (segmentsIntersect(a, b, c, d)) return true;
            }
        }
        return false;
    }

    // Tarjan SCC
    static int time, sccCnt;
    static int[] disc, low, comp;
    static boolean[] inStack;
    static ArrayDeque<Integer> stack;

    static void tarjan(int u, List<Integer>[] g) {
        disc[u] = low[u] = ++time;
        stack.push(u);
        inStack[u] = true;
        for (int v : g[u]) {
            if (disc[v] == 0) {
                tarjan(v, g);
                low[u] = Math.min(low[u], low[v]);
            } else if (inStack[v]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
        if (low[u] == disc[u]) {
            while (true) {
                int x = stack.pop();
                inStack[x] = false;
                comp[x] = sccCnt;
                if (x == u) break;
            }
            sccCnt++;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        double d = fs.nextDouble();

        Triangle[] tris = new Triangle[n];
        for (int i = 0; i < n; i++) {
            double x1 = fs.nextDouble(), y1 = fs.nextDouble();
            double x2 = fs.nextDouble(), y2 = fs.nextDouble();
            double x3 = fs.nextDouble(), y3 = fs.nextDouble();
            tris[i] = new Triangle(new Point(x1, y1), new Point(x2, y2), new Point(x3, y3));
        }

        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int[][] sides = tris[i].equalSides();
            Rect r1 = buildLightRect(tris[i], sides[0][0], sides[0][1], d);
            Rect r2 = buildLightRect(tris[i], sides[1][0], sides[1][1], d);

            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                boolean lit = false;
                if (r1 != null && triangleIntersectsRect(tris[j], r1)) lit = true;
                if (!lit && r2 != null && triangleIntersectsRect(tris[j], r2)) lit = true;
                if (lit) g[i].add(j);
            }
        }

        disc = new int[n];
        low = new int[n];
        comp = new int[n];
        inStack = new boolean[n];
        stack = new ArrayDeque<>();
        time = 0;
        sccCnt = 0;

        for (int i = 0; i < n; i++) if (disc[i] == 0) tarjan(i, g);

        int[] indeg = new int[sccCnt];
        for (int u = 0; u < n; u++) {
            for (int v : g[u]) {
                if (comp[u] != comp[v]) indeg[comp[v]]++;
            }
        }

        int ans = 0;
        for (int i = 0; i < sccCnt; i++) if (indeg[i] == 0) ans++;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) { in = is; }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

