import sys
import math

EPS = 1e-2 + 1e-12

def same_point(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1]) <= EPS

def dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])

def point_segment_distance(p, a, b):
    ax, ay = a
    bx, by = b
    px, py = p
    vx, vy = bx - ax, by - ay
    wx, wy = px - ax, py - ay
    vv = vx * vx + vy * vy
    if vv == 0:
        return math.hypot(px - ax, py - ay)
    t = (wx * vx + wy * vy) / vv
    if t < 0:
        cx, cy = ax, ay
    elif t > 1:
        cx, cy = bx, by
    else:
        cx, cy = ax + t * vx, ay + t * vy
    return math.hypot(px - cx, py - cy)

def point_on_segment(p, a, b):
    return point_segment_distance(p, a, b) <= EPS

def line_intersection(p1, p2, q1, q2):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = q1
    x4, y4 = q2
    den = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4)
    if abs(den) < 1e-12:
        return None
    px = ((x1*y2 - y1*x2)*(x3-x4) - (x1-x2)*(x3*y4 - y3*x4)) / den
    py = ((x1*y2 - y1*x2)*(y3-y4) - (y1-y2)*(x3*y4 - y3*x4)) / den
    return (px, py)

def segment_intersection(a, b, c, d):
    # returns intersection point if segments intersect at a single point
    inter = line_intersection(a, b, c, d)
    if inter is None:
        # parallel/collinear; problem geometry avoids touching/overlap, so ignore
        return None
    if point_on_segment(inter, a, b) and point_on_segment(inter, c, d):
        return inter
    return None

def is_isosceles(tri):
    pts = tri
    ds = [dist(pts[0], pts[1]), dist(pts[1], pts[2]), dist(pts[2], pts[0])]
    return (abs(ds[0]-ds[1]) <= EPS or abs(ds[1]-ds[2]) <= EPS or abs(ds[2]-ds[0]) <= EPS)

def apex_and_base(tri):
    p = tri
    d01 = dist(p[0], p[1])
    d12 = dist(p[1], p[2])
    d20 = dist(p[2], p[0])

    # apex is common endpoint of equal sides
    if abs(d01 - d12) <= EPS:
        return p[1], p[0], p[2]  # apex, base1, base2
    if abs(d12 - d20) <= EPS:
        return p[2], p[1], p[0]
    return p[0], p[1], p[2]

def ray_segment_intersection(origin, direction, a, b):
    ox, oy = origin
    dx, dy = direction
    ax, ay = a
    bx, by = b
    sx, sy = bx - ax, by - ay

    den = dx * sy - dy * sx
    if abs(den) < 1e-12:
        return None

    qx, qy = ax - ox, ay - oy
    t = (qx * sy - qy * sx) / den
    u = (qx * dy - qy * dx) / den

    if t < -EPS or u < -EPS or u > 1 + EPS:
        return None
    return (ox + t * dx, oy + t * dy, t)

def point_in_triangle(pt, tri):
    # includes boundary within EPS
    a, b, c = tri
    def cross(o, p, q):
        return (p[0]-o[0])*(q[1]-o[1]) - (p[1]-o[1])*(q[0]-o[0])
    c1 = cross(a, b, pt)
    c2 = cross(b, c, pt)
    c3 = cross(c, a, pt)
    pos = (c1 >= -EPS and c2 >= -EPS and c3 >= -EPS)
    neg = (c1 <= EPS and c2 <= EPS and c3 <= EPS)
    return pos or neg

def illuminated(i, j, triangles, L):
    # Triangle i illuminates rectangle extending from its base outward by length L.
    tri_i = triangles[i]
    tri_j = triangles[j]

    apex, b1, b2 = apex_and_base(tri_i)

    # base midpoint
    mx = (b1[0] + b2[0]) / 2.0
    my = (b1[1] + b2[1]) / 2.0

    # outward direction = from apex through midpoint, continued away from apex
    vx = mx - apex[0]
    vy = my - apex[1]
    norm = math.hypot(vx, vy)
    if norm < 1e-12:
        return False
    ux, uy = vx / norm, vy / norm

    # rectangle corners: b1, b2, b2+uL, b1+uL
    c1 = b1
    c2 = b2
    c3 = (b2[0] + ux * L, b2[1] + uy * L)
    c4 = (b1[0] + ux * L, b1[1] + uy * L)
    rect = [c1, c2, c3, c4]

    # Check triangle-rectangle intersection/touch
    # 1) any triangle vertex in rectangle
    def point_in_convex_quad(p, q):
        def cross(o, a, b):
            return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
        vals = [cross(q[k], q[(k+1)%4], p) for k in range(4)]
        pos = all(v >= -EPS for v in vals)
        neg = all(v <= EPS for v in vals)
        return pos or neg

    for p in tri_j:
        if point_in_convex_quad(p, rect):
            return True

    # 2) any rectangle corner in triangle
    for p in rect:
        if point_in_triangle(p, tri_j):
            return True

    # 3) any edge intersections
    tri_edges = [(tri_j[0], tri_j[1]), (tri_j[1], tri_j[2]), (tri_j[2], tri_j[0])]
    rect_edges = [(rect[0], rect[1]), (rect[1], rect[2]), (rect[2], rect[3]), (rect[3], rect[0])]
    for e1 in tri_edges:
        for e2 in rect_edges:
            if segment_intersection(e1[0], e1[1], e2[0], e2[1]) is not None:
                return True

    return False

def kosaraju_scc(n, g, rg):
    used = [False] * n
    order = []

    sys.setrecursionlimit(1000000)

    def dfs(v):
        used[v] = True
        for to in g[v]:
            if not used[to]:
                dfs(to)
        order.append(v)

    for v in range(n):
        if not used[v]:
            dfs(v)

    comp = [-1] * n

    def rdfs(v, c):
        comp[v] = c
        for to in rg[v]:
            if comp[to] == -1:
                rdfs(to, c)

    j = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, j)
            j += 1

    return j, comp

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    L = float(next(it))

    triangles = []
    for _ in range(n):
        pts = []
        for _ in range(3):
            x = float(next(it))
            y = float(next(it))
            pts.append((x, y))
        triangles.append(pts)

    g = [[] for _ in range(n)]
    rg = [[] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j and illuminated(i, j, triangles, L):
                g[i].append(j)
                rg[j].append(i)

    scc_cnt, comp = kosaraju_scc(n, g, rg)

    indeg = [0] * scc_cnt
    for v in range(n):
        for to in g[v]:
            if comp[v] != comp[to]:
                indeg[comp[to]] += 1

    ans = sum(1 for d in indeg if d == 0)
    print(ans)

if __name__ == "__main__":
    main()
